mapper.select:
SELECT

FROM ts_feedback f
LEFT JOIN sys_user u ON u.id = f.user_id
WHERE f.is_deleted = 0

    AND f.user_id = #{query.ownerUserId}


    AND f.type = #{query.type}


    AND f.status = #{query.status}


    AND (
        f.title LIKE CONCAT('%', #{query.keyword}, '%')
        OR f.content LIKE CONCAT('%', #{query.keyword}, '%')
    )



        ORDER BY f.like_count DESC, f.created_at DESC, f.id DESC


        ORDER BY f.created_at DESC, f.id DESC
